# Writes the hedra command files of orbit-defense's world and game pieces (everything but the hero
# satellite, which has its own p1/p2 files in models/satellite). Run from models/env:
#   /usr/bin/python3 make_env.py
# hedra: up Z, front -Y (the camera looks along +Y at the play plane y = 0, i.e. the GLB's z = 0).
# Colours are exact Berry Nebula hexes (sRGB 0..1) so the bake snaps with colour error 0.000.
import math, random

HEX = {"cyan": "6ceded", "aqua": "6cb9c9", "blue": "6d85a5", "mauve": "6e5181",
       "plum": "6f1d5c", "berry": "4f1446", "wine": "2e0a30", "night": "0d001a"}
def col(n, emit=False):
    h = HEX[n]; r, g, b = (int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
    s = f"--base-color {r:.3f} {g:.3f} {b:.3f}"
    return s + (f" --emission {r:.3f} {g:.3f} {b:.3f}" if emit else "")

def rim(theta_deg, r):
    """a point on the play plane at angle theta (0 = right, 90 = up) and the hedra Y rotation that
    turns an object's +Z (up) to point outwards there"""
    t = math.radians(theta_deg)
    return (r * math.cos(t), 0.0, r * math.sin(t)), 90.0 - theta_deg

def write(name, text):
    with open(f"{name}.txt", "w") as f:
        f.write(text.strip() + "\n")

R = 1.4  # planet radius

# ---------------------------------------------------------------- planet (static, bone 0)
p = [f"""# The planet: a radius {R} m low-poly sphere (icosphere, 2 subdivisions, jittered), berry rock with two
# mauve seas, rock spires between the house sites. The back half (never seen by the
# face-on camera) is deleted. Generated by make_env.py.
new
material new Rock {col('berry')} --no-slot
material new Sea {col('mauve')} --no-slot
material new Spire {col('mauve')} --no-slot
add mesh ico-sphere --name Planet --radius {R} --subdivisions 2 --location 0 0 0
material assign Rock
mode edit
select vert where "true"
randomize --amount 0.05 --seed 3
select face where "pos.y > 0.45"
delete only-faces
select face where "sqrt((pos.x+0.55)*(pos.x+0.55) + (pos.y+1.1)*(pos.y+1.1) + (pos.z-0.45)*(pos.z-0.45)) < 0.62"
select face where "sqrt((pos.x-0.75)*(pos.x-0.75) + (pos.y+0.95)*(pos.y+0.95) + (pos.z+0.6)*(pos.z+0.6)) < 0.5" --extend
material assign Sea
mode object
"""]
for i, th in enumerate([90, 180, 270, 0, 20, 160]):
    big = i < 4
    (x, y, z), ry = rim(th, R - 0.08)
    h = 0.5 if big else 0.32
    p.append(f"""add mesh cone --name Spire{i} --vertices 5 --radius1 {0.13 if big else 0.1} --radius2 0 --depth {h} --location 0 0 {h/2}
apply --location
set rotation 0 {ry:.2f} 0
set location {x:.3f} {y - 0.15:.3f} {z:.3f}
material assign Spire""")
p.append("""select all
shade flat
export planet.glb""")
write("planet", "\n".join(p))

# ---------------------------------------------------------------- sky (static): stars, nebula, moon
rnd = random.Random(11)
s = [f"""# The sky behind the planet: a field of star specks (unlit), a few big ones as crosses, soft nebula
# clouds (flat unlit discs) and a small lit moon, all 8 to 12 m behind the play plane (hedra +Y).
# Generated by make_env.py (random positions, seed 11).
new
material new Star {col('blue', True)} --no-slot
material new Bright {col('cyan', True)} --no-slot
material new Nebula {col('wine', True)} --no-slot
material new Core {col('berry', True)} --no-slot
material new Moon {col('mauve')} --no-slot
"""]
stars = []
while len(stars) < 48:
    x, z = rnd.uniform(-7.4, 7.4), rnd.uniform(-4.6, 4.6)
    if math.hypot(x, z) < 2.6 or any(math.hypot(x - a, z - b) < 0.9 for a, b in stars):
        continue
    stars.append((x, z))
for i, (x, z) in enumerate(stars):
    big = i % 12 == 0
    sz = 0.1 if not big else 0.09
    s.append(f"add mesh cube --name S{i} --size {sz} --location {x:.2f} 10 {z:.2f}")
    if big:   # a cross: two bars
        s.append(f"scale 3.2 1 1\napply --scale\nmaterial assign Bright")
        s.append(f"add mesh cube --name SV{i} --size {sz} --location {x:.2f} 10 {z:.2f}\nscale 1 1 3.2\napply --scale\nmaterial assign Bright")
    else:
        s.append("material assign " + ("Bright" if i % 5 == 0 else "Star"))
for i, (x, z, w, h, core) in enumerate([(-4.2, 2.2, 3.4, 1.4, True), (-2.6, 3.0, 2.0, 0.9, False),
                                         (4.6, -2.4, 3.0, 1.2, True), (3.0, -3.3, 2.2, 0.8, False),
                                         (5.4, 2.9, 1.8, 0.7, False), (-5.6, -2.8, 2.0, 0.8, False)]):
    s.append(f"""add mesh cylinder --name Neb{i} --vertices 9 --radius 0.5 --depth 0.05 --location {x} 12 {z} --rotation 90 {rnd.uniform(0, 40):.1f} 0
apply --rotation
scale {w} 1 {h}
apply --scale
material assign Nebula""")
    if core:
        s.append(f"""add mesh cylinder --name Core{i} --vertices 7 --radius 0.5 --depth 0.05 --location {x + 0.2} 11.8 {z + 0.1} --rotation 90 15 0
apply --rotation
scale {w * 0.45} 1 {h * 0.45}
apply --scale
material assign Core""")
s.append("""add mesh ico-sphere --name Moon --radius 0.42 --subdivisions 1 --location -4.9 7 2.6
material assign Moon
select all
shade flat
export sky.glb""")
write("sky", "\n".join(s))

# ---------------------------------------------------------------- houses (game bones, the lives)
write("hut", f"""# A hut: the origin at the ground under its centre, up Z. Walls aqua, a pitched mauve roof,
# a glowing window on the front (proud of the wall by a splat spacing) and a chimney. One bone each.
new
material new Wall {col('aqua')} --no-slot
material new Roof {col('mauve')} --no-slot
material new Window {col('cyan', True)} --no-slot
add mesh cube --name Walls --size 1 --location 0 0 0.17
scale 0.44 0.36 0.34
apply --scale
material assign Wall
add mesh cylinder --name Roof --vertices 3 --radius 0.33 --depth 0.42 --location 0 0 0.43 --rotation 90 0 90
apply --rotation
scale 1 1 0.75
apply --scale
material assign Roof
add mesh cube --name Chimney --size 1 --location 0.13 0 0.55
scale 0.11 0.11 0.2
apply --scale
material assign Roof
add mesh cube --name Window --size 1 --location -0.06 -0.2 0.17
scale 0.13 0.06 0.13
apply --scale
material assign Window
select all
shade flat
export hut.glb""")

write("dome", f"""# A dome house: a faceted half-dome on a ring wall, a glowing door, a mast with a cyan beacon.
# Origin at the ground under its centre, up Z. One bone each.
new
material new Wall {col('aqua')} --no-slot
material new Base {col('mauve')} --no-slot
material new Window {col('cyan', True)} --no-slot
add mesh cylinder --name Ring --vertices 8 --radius 0.27 --depth 0.12 --location 0 0 0.06
material assign Base
add mesh uv-sphere --name Dome --segments 8 --rings 4 --radius 0.25 --location 0 0 0.12
material assign Wall
mode edit
select vert where "pos.z < -0.01"
delete
mode object
add mesh cube --name Door --size 1 --location 0 -0.24 0.11
scale 0.11 0.07 0.16
apply --scale
material assign Window
add mesh cube --name Mast --size 1 --location 0.08 0 0.45
scale 0.09 0.09 0.22
apply --scale
material assign Base
add mesh cube --name Beacon --size 1 --location 0.08 0 0.59
scale 0.11 0.11 0.11
apply --scale
material assign Window
select all
shade flat
export dome.glb""")

write("rubble", f"""# Rubble left where a house was hit: a few tilted dark blocks. Origin at the ground, up Z.
new
material new Rubble {col('berry')} --no-slot
material new Ember {col('plum', True)} --no-slot
add mesh cube --name R0 --size 1 --location -0.12 0 0.06
scale 0.2 0.22 0.12
apply --scale
set rotation 0 18 0
add mesh cube --name R1 --size 1 --location 0.1 0 0.07
scale 0.22 0.2 0.14
apply --scale
set rotation 0 -25 10
add mesh cube --name R2 --size 1 --location 0 -0.02 0.15
scale 0.14 0.14 0.12
apply --scale
set rotation 30 0 40
select R0 R1 R2
material assign Rubble
add mesh cube --name Glow --size 1 --location 0 -0.1 0.05
scale 0.12 0.06 0.08
apply --scale
material assign Ember
select all
shade flat
export rubble.glb""")

# ---------------------------------------------------------------- meteors, trail, effects
def rock(name, r, seed, what):
    return f"""# {what}: a jittered icosahedron of radius {r} m centred on the origin (its pivot), mauve rock
# with a few glowing plum faces (hot spots). One bone each, tumbled by the game.
new
material new Rock {col('mauve')} --no-slot
material new Hot {col('plum', True)} --no-slot
add mesh ico-sphere --name {name} --radius {r} --subdivisions 1 --location 0 0 0
material assign Rock
mode edit
select vert where "true"
randomize --amount {r * 0.22:.3f} --seed {seed}
select face where "pos.x + pos.z > {r * 0.9:.3f}"
material assign Hot
mode object
shade flat
export {name}.glb"""
write("meteor", rock("meteor", 0.3, 5, "A small meteor"))
write("boulder", rock("boulder", 0.46, 8, "A big meteor (two hits)"))

write("trail", f"""# A meteor's fiery tail: an outer plum cone and a mauve inner one, base at the origin (the meteor's
# centre) tapering along +Z for 1.4 m; unlit. The game points +Z away from the meteor's motion.
new
material new Outer {col('plum', True)} --no-slot
material new Inner {col('mauve', True)} --no-slot
add mesh cone --name Outer --vertices 6 --radius1 0.26 --radius2 0.03 --depth 1.4 --location 0 0.06 0.7
material assign Outer
add mesh cone --name Inner --vertices 6 --radius1 0.16 --radius2 0.02 --depth 0.75 --location 0 -0.02 0.4
material assign Inner
select all
shade flat
export trail.glb""")

write("bolt", f"""# A cannon bolt: a stretched octahedron 0.15 x 0.5 m along +Z (the game turns +Z along its flight),
# bright cyan core, aqua rim; unlit.
new
material new Core {col('cyan', True)} --no-slot
material new Rim {col('aqua', True)} --no-slot
add mesh ico-sphere --name Bolt --radius 0.5 --subdivisions 1 --location 0 0 0
scale 0.2 0.2 0.55
apply --scale
material assign Rim
add mesh ico-sphere --name Core --radius 0.5 --subdivisions 1 --location 0 -0.04 0.05
scale 0.12 0.12 0.36
apply --scale
material assign Core
select all
shade flat
export bolt.glb""")

b = [f"""# A burst: eight spikes round a core in the play plane, 1.4 m across, unlit cyan; the game pops it
# (scale 0.3 -> 1 -> gone over a quarter second). Baked at full size: the game only scales it down.
new
material new Spike {col('aqua', True)} --no-slot
material new Core {col('cyan', True)} --no-slot
add mesh ico-sphere --name Core --radius 0.24 --subdivisions 1 --location 0 -0.05 0
material assign Core"""]
for i in range(8):
    a = i * 45 + 22.5
    L = 0.7 if i % 2 == 0 else 0.48
    (x, y, z), ry = rim(a, 0.0)
    b.append(f"""add mesh cone --name Sp{i} --vertices 4 --radius1 0.1 --radius2 0 --depth {L} --location 0 0 {L/2 + 0.12}
apply --location
set rotation 0 {ry:.1f} 0
material assign Spike""")
b.append("select all\nshade flat\nexport burst.glb")
write("burst", "\n".join(b))

write("debris", f"""# A chunk of meteor debris: a tiny tumbling rock (the game flings a pool of them out of each burst).
new
material new Rock {col('plum')} --no-slot
add mesh ico-sphere --name Chunk --radius 0.09 --subdivisions 1 --location 0 0 0
material assign Rock
mode edit
select vert where "true"
randomize --amount 0.02 --seed 2
mode object
shade flat
export debris.glb""")

write("puff", f"""# A dust puff where a meteor strikes the planet: three overlapping faceted balls, lit mauve.
new
material new Dust {col('mauve')} --no-slot
add mesh ico-sphere --name P0 --radius 0.3 --subdivisions 1 --location 0 0 0.2
add mesh ico-sphere --name P1 --radius 0.22 --subdivisions 1 --location -0.28 -0.05 0.12
add mesh ico-sphere --name P2 --radius 0.24 --subdivisions 1 --location 0.27 -0.05 0.15
select P0 P1 P2
material assign Dust
active P0
join
shade flat
export puff.glb""")

write("flash", f"""# The muzzle flash: a four-pointed star 0.5 m across in the play plane, unlit cyan.
new
material new Flash {col('cyan', True)} --no-slot
add mesh cube --name H --size 1 --location 0 0 0
scale 0.5 0.08 0.12
apply --scale
add mesh cube --name V --size 1 --location 0 0 0
scale 0.12 0.08 0.5
apply --scale
select H V
material assign Flash
active H
join
shade flat
export flash.glb""")
print("wrote planet sky hut dome rubble meteor boulder trail bolt burst debris puff flash")
